describe('Image Scaling for Mobile Users', () => {
    beforeEach(() => {
        cy.visit('/'); // Replace with the actual URL of the application
    });

    it('should scale down images to fit the screen width on mobile', () => {
        cy.viewport('iphone-6'); // Set viewport to mobile size
        cy.get('img').each(($img) => {
            const imgWidth = $img.width();
            cy.wrap($img).invoke('attr', 'naturalWidth').then((naturalWidth) => {
                expect(parseInt(naturalWidth)).to.be.greaterThan(imgWidth);
            });
        });
    });

    it('should not overflow the screen width with images on mobile', () => {
        cy.viewport('iphone-6'); // Set viewport to mobile size
        cy.get('img').each(($img) => {
            cy.wrap($img).should('have.css', 'max-width').and('equal', '100%');
        });
    });
});
